const removeDuplicates = (arr) => {
  if (!Array.isArray(arr)) {
    throw new Error("Input must be an array.");
  }

  const seen = {};
  const result = [];
  let i = 0;

  while (i < arr.length) {
    const element = arr[i];
    if (!seen[element]) {
      result.push(element);
      seen[element] = true;
    }
    i++;
  }

  return result;
};

