const calculateAverage = (arr) => {
  if (!Array.isArray(arr) || arr.length === 0) {
    return 0;
  }

  let sum = 0;
  for (let i = 0; i < arr.length; i++) {
    sum += arr[i];
  }

  const average = sum / arr.length;
  return average;
};

// Example usage:
