const swapKeysAndValues = (obj) => {
  const swapped = {};
  const keys = Object.keys(obj);
  let i = 0;

  while (i < keys.length) {
    const key = keys[i];
    const value = obj[key];
    swapped[value] = key;
    i++;
  }

  return swapped;
};

