function calculateCircleArea(radius) {
  if (typeof radius !== 'number') {
    throw new Error("Radius must be a number.");
  }

  if (radius < 0) {
    throw new Error("Radius cannot be negative.");
  }

  let area = Math.PI * radius * radius;
  return area;
}

// Example usage and testing:
let area1 = calculateCircleArea(1);
console.log(area1 === Math.PI);

let area2 = calculateCircleArea(2);
console.log(area2 === 4 * Math.PI);

try {
  calculateCircleArea(-5);
} catch (e) {
  console.log(e.message === "Radius cannot be negative.");
}

try {
  calculateCircleArea("abc");
} catch (e) {
  console.log(e.message === "Radius must be a number.");
}

let area3 = calculateCircleArea(0);
console.log(area3 === 0);

let piValue = Math.PI;
console.log(calculateCircleArea(1) === piValue);

