function fizzBuzz(n) {
  let result = [];
  for (let i = 1; i <= n; i++) {
    let output = "";
    const isMultipleOf3 = (i % 3 === 0);
    const isMultipleOf5 = (i % 5 === 0);

    if (isMultipleOf3) {
      output += "Fizz";
    };

    if (isMultipleOf5) {
      output += "Buzz";
    };

    if (output === "") {
      result.push(i);
    } else {
      result.push(output);
    };
  }
  return result;
};

