const areAnagrams = (str1, str2) => {
  const normalize = (str) => {
    return str.toLowerCase().replace(/\s/g, '').split('').sort().join('');
  };

  const normalizedStr1 = normalize(str1);
  const normalizedStr2 = normalize(str2);

  const result = normalizedStr1 === normalizedStr2;
  return result;
};

// Example usage:
