const strB = "silent";
const strC = "Hello World";
const strD = "world hello";
const strE = "anagram";
const strF = "nagaram";
const strG = "rat";
const strH = "car";

const output1 = areAnagrams(strA, strB);
const output2 = areAnagrams(strC, strD);
const output3 = areAnagrams(strE, strF);
const output4 = areAnagrams(strG, strH);

