function rollDice(sides) {
  let min = 1;
  let max = sides;

  if (typeof sides !== 'number' || !Number.isInteger(sides) || sides < 1) {
    throw new Error("Sides must be a positive integer.");
  };

  let randomNumber = Math.random();
  let scaledNumber = randomNumber * (max - min + 1);
  let floorNumber = Math.floor(scaledNumber);
  let result = floorNumber + min;

  return result;
};

