function truncateString(str, maxLength) {
  const ellipsis = "...";
  let result = str;

  if (str.length > maxLength) {
    if (maxLength <= ellipsis.length) {
      result = ellipsis;
    } else {
      result = str.slice(0, maxLength - ellipsis.length) + ellipsis;
    }
  }

  return result;
};

