function getFileExtension(filename) {
  const parts = filename.split('.');
  const numParts = parts.length;

  if (numParts <= 1) {
    return '';
  }

  const lastPart = parts[numParts - 1];
  const secondLastPart = parts[numParts - 2];

  if (secondLastPart === '' && numParts === 2) { // Handles cases like ".bashrc" or "foo."
    return '';
  }

  if (lastPart === '') { // Handles cases like "archive.tar."
    return '';
  }

  if (secondLastPart === 'tar' && (lastPart === 'gz' || lastPart === 'bz2' || lastPart === 'xz')) {
    return lastPart;
  }

  return lastPart;
}

