function parseCsvLine(line) {
  const values = [];
  let currentWord = "";
  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    if (char === ',') {
      values.push(currentWord.trim());
      currentWord = "";
    } else {
      currentWord += char;
    }
  }
  values.push(currentWord.trim());
  return values;
}

