function hexToRgb(hexColor) {
  let hex = hexColor.startsWith('#') ? hexColor.slice(1) : hexColor;

  if (hex.length !== 6) {
    throw new Error("Invalid hex color format; expected 6 characters after optional '#'");
  }

  const rHex = hex.substring(0, 2);
  const gHex = hex.substring(2, 4);
  const bHex = hex.substring(4, 6);

  const r = parseInt(rHex, 16);
  const g = parseInt(gHex, 16);
  const b = parseInt(bHex, 16);

  if (isNaN(r) || isNaN(g) || isNaN(b)) {
    throw new Error("Invalid hex color format; characters must be hexadecimal");
  }

  return [r, g, b];
}

