const longestCommonPrefix = (strs) => {
  if (strs.length === 0) return "";

  let prefix = strs[0];
  for (let i = 1; i < strs.length; i++) {
    let currentWord = strs[i];
    let j = 0;
    while (j < prefix.length && j < currentWord.length && prefix[j] === currentWord[j]) {
      j++;
    }
    prefix = prefix.substring(0, j);
    if (prefix === "") {
      return "";
    }
  }
  return prefix;
};

