function caesarCipher(text, shift) {
  let result = "";
  let s = shift % 26;

  for (let i = 0; i < text.length; i++) {
    let char = text[i];

    if (char >= 'a' && char <= 'z') {
      let code = char.charCodeAt(0);
      code = ((code - 97 + s + 26) % 26) + 97;
      result += String.fromCharCode(code);
    } else if (char >= 'A' && char <= 'Z') {
      let code = char.charCodeAt(0);
      code = ((code - 65 + s + 26) % 26) + 65;
      result += String.fromCharCode(code);
    } else {
      result += char;
    }
  }
  return result;
};

