function largeFactorial(n) {
  let result = "1";

  for (let i = 2; i <= n; i++) {
    let carry = 0;
    let tempResult = "";

    for (let j = result.length - 1; j >= 0; j--) {
      let digit = parseInt(result[j]);
      let product = digit * i + carry;
      tempResult = (product % 10) + tempResult;
      carry = Math.floor(product / 10);
    }

    while (carry > 0) {
      tempResult = (carry % 10) + tempResult;
      carry = Math.floor(carry / 10);
    }
    result = tempResult;
  }
  return result;
}

