function stringPermutations(str) {
  const result = [];
  const uniquePermutations = new Set();

  if (str.length === 0) {
    return [""];
  }

  function permute(currentPermutation, remainingChars) {
    if (remainingChars.length === 0) {
      uniquePermutations.add(currentPermutation);
      return;
    }

    for (let i = 0; i < remainingChars.length; i++) {
      const char = remainingChars[i];
      const newRemaining = remainingChars.slice(0, i) + remainingChars.slice(i + 1);
      permute(currentPermutation + char, newRemaining);
    }
  }

  permute("", str);
  return Array.from(uniquePermutations);
}

