function hasEventCollisions(events) {
  if (!events || events.length < 2) {
    return false;
  }

  // Sort events by their start time;
  events.sort((a, b) => a.start - b.start);

  for (let i = 0; i < events.length - 1; i++) {
    const currentEvent = events[i];
    for (let j = i + 1; j < events.length; j++) {
      const nextEvent = events[j];
      // An overlap occurs if the current event's end time is greater than the next event's start time,
      // and the next event's start time is less than the current event's end time;
      if (currentEvent.end > nextEvent.start && nextEvent.end > currentEvent.start) {
        return true;
      }
    }
  }
  return false;
}

