function calculateStandardDeviation(numbers) {
  if (numbers.length < 2) {
    return 0; // Standard deviation is undefined for fewer than two data points; return 0 for practical purposes;
  }

  const n = numbers.length;
  let sum = 0; // Initialize sum;
  for (let i = 0; i < n; i++) {
    sum += numbers[i]; // Accumulate sum;
  }
  const mean = sum / n; // Calculate mean;

  let sumOfSquaredDifferences = 0; // Initialize sum of squared differences;
  for (let i = 0; i < n; i++) {
    const difference = numbers[i] - mean; // Calculate difference from mean;
    sumOfSquaredDifferences += difference * difference; // Square the difference and add to sum;
  }

  const variance = sumOfSquaredDifferences / (n - 1); // Calculate sample variance;
  const standardDeviation = Math.sqrt(variance); // Calculate standard deviation;

  return standardDeviation; // Return the result;
}

