function replaceAllOccurrences(text, find, replace) {
  let result = '';
  let lastIndex = 0;
  let findLength = find.length;
  let textLength = text.length;

  for (let i = 0; i <= textLength - findLength; i++) {
    let sub = text.substring(i, i + findLength);
    if (sub === find) {
      result += text.substring(lastIndex, i);
      result += replace;
      lastIndex = i + findLength;
      i += findLength - 1; // Adjust i to prevent re-checking the replaced part
    }
  }

  result += text.substring(lastIndex, textLength); // Append remaining part;
  return result;
}

