function rotateArray(nums, k) {
  let n = nums.length;
  k = k % n; // Handle cases where k is greater than array length;

  if (k === 0) {
    return nums; // No rotation needed;
  }

  let rotated = new Array(n); // Create a new array for the rotated result;

  for (let i = 0; i < n; i++) {
    rotated[(i + k) % n] = nums[i]; // Place elements in their new positions;
  }

  for (let i = 0; i < n; i++) {
    nums[i] = rotated[i]; // Copy elements back to the original array;
  }

  return nums; // Return the modified array;
}

