  var decimal = 0;
  var power = 0;
  var i;

  for (i = binaryStr.length - 1; i >= 0; i--) {
    var digit = parseInt(binaryStr[i], 10);
    if (digit === 1) {
      decimal += Math.pow(2, power);
    }
    power++;
  }

