const range = (start, end, step = 1) => {
  const result = [];
  let current = start;

  if (step === 0) {
    if (start === end) {
      return [start];
    } else {
      return [];
    }
  }

  if (step > 0) {
    while (current <= end) {
      result.push(current);
      current += step;
    }
  } else { // step < 0
    while (current >= end) {
      result.push(current);
      current += step;
    }
  }

  return result;
};

