class Stack {
  constructor() {
    this.elements = [];
  }

  push(element) {
    this.elements.push(element);
  }

  pop() {
    if (this.isEmpty()) {
      return null;
    }
    return this.elements.pop();
  }

  isEmpty() {
    return this.elements.length === 0;
  }

  peek() {
    if (this.isEmpty()) {
      return null;
    }
    return this.elements[this.elements.length - 1];
  }

  size() {
    return this.elements.length;
  }
}

