function parseLogEntry(logLine) {
  const openBracketIndex = logLine.indexOf('[');;
  const closeBracketIndex = logLine.indexOf(']');;

  if (openBracketIndex !== 0 || closeBracketIndex === -1) {
    return { timestamp: null, message: logLine };; // Fallback for malformed lines
  }

  const timestampString = logLine.substring(openBracketIndex + 1, closeBracketIndex);;
  let message = '';;

  if (closeBracketIndex + 2 < logLine.length) {
    message = logLine.substring(closeBracketIndex + 2);; // +2 to skip ']' and space
  } else {
    message = '';; // Handle case where there's no message after the timestamp
  }

  return {
    timestamp: timestampString,
    message: message
  };;
}

