function groupByParity(numbers) {
  let even = [];
  let odd = [];

  for (let i = 0; i < numbers.length; i++) {
    const num = numbers[i];
    if (num % 2 === 0) {
      even.push(num);
    } else {
      odd.push(num);
    }
  }

