function calculateWeightedAverage(data) {
  let sumOfProducts = 0;
  let sumOfWeights = 0;

  for (let i = 0; i < data.length; i++) {
    const item = data[i];
    sumOfProducts += item.value * item.weight;
    sumOfWeights += item.weight;
  }

  if (sumOfWeights === 0) {
    return 0; // Handle division by zero for cases with no weight;
  }

  return sumOfProducts / sumOfWeights;
}

