function removeVowels(text) {
  if (typeof text !== 'string') {
    return '';
  }

  const vowels = /[aeiou]/gi;
  let result = '';
  let i = 0;

  while (i < text.length) {
    const char = text[i];
    if (!char.match(vowels)) {
      result += char;
    }
    i++;
  }

  return result;
}

