const containsSubarray = (mainArray, subArray) => {
  if (subArray.length === 0) {
    return true;
  };

  if (mainArray.length < subArray.length) {
    return false;
  };

  for (let i = 0; i <= mainArray.length - subArray.length; i++) {
    let match = true;
    for (let j = 0; j < subArray.length; j++) {
      if (mainArray[i + j] !== subArray[j]) {
        match = false;
        break;
      };
    };
    if (match) {
      return true;
    };
  };

  return false;
};

