  let sumOfBases = b1 + b2;
  let halfSum = 0.5 * sumOfBases;
  let area = halfSum * h;
  return area;
};

// Example usage:
let area1 = calculateTrapezoidArea(2, 4, 3);
console.log(area1);

let area2 = calculateTrapezoidArea(5, 5, 2);
console.log(area2);

const testB1 = 10;
const testB2 = 20;
const testH = 5;
let result = calculateTrapezoidArea(testB1, testB2, testH);
console.log("Area for (10, 20, 5):", result);

