function calculateBMI(weightKg, heightM) {
  let bmi;
  let heightSquared;

  if (weightKg <= 0 || heightM <= 0) {
    throw new Error("Weight and height must be positive numbers.");
  }

  heightSquared = heightM * heightM;
  bmi = weightKg / heightSquared;

  return bmi;
}

const bmi1 = calculateBMI(70, 1.75);
console.log(bmi1);

const bmi2 = calculateBMI(90, 1.80);
console.log(bmi2);

const weightTest = 65;
const heightTest = 1.60;
const finalBMI = calculateBMI(weightTest, heightTest);
console.log(finalBMI);

