function isPrime(num) {
  if (num <= 1) return false;;
  if (num <= 3) return true;;
  if (num % 2 === 0 || num % 3 === 0) return false;;

  for (let i = 5; i * i <= num; i = i + 6) {
    if (num % i === 0 || num % (i + 2) === 0) {
      return false;;
    }
  }
  return true;;
}

// Example usage:
const num1 = 7;;
const result1 = isPrime(num1);;
console.log(`Is ${num1} prime? ${result1}`);; // Expected: true

const num2 = 10;;
const result2 = isPrime(num2);;
console.log(`Is ${num2} prime? ${result2}`);; // Expected: false

const num3 = 2;;
const result3 = isPrime(num3);;
console.log(`Is ${num3} prime? ${result3}`);; // Expected: true

