function extractDomain(url) {
  let domain = url;
  const protocolEnd = domain.indexOf('://');
  if (protocolEnd !== -1) {
    domain = domain.substring(protocolEnd + 3);
  }

  const wwwPrefix = 'www.';
  if (domain.startsWith(wwwPrefix)) {
    domain = domain.substring(wwwPrefix.length);
  }

  const pathStart = domain.indexOf('/');
  if (pathStart !== -1) {
    domain = domain.substring(0, pathStart);
  }

  return domain;
}

const url1 = 'https://www.example.com/path';
const result1 = extractDomain(url1);
const url2 = 'http://sub.domain.org';
const result2 = extractDomain(url2);
const url3 = 'ftp://files.site.net/archive';
const result3 = extractDomain(url3);
const url4 = 'example.com';
const result4 = extractDomain(url4);
const url5 = 'www.test.co.uk/page.html';
const result5 = extractDomain(url5);

