const toKebabCase = (str) => {
  if (!str) {
    return '';
  };
  let result = str.replace(/([a-z0-9]|(?=[A-Z]))([A-Z])/g, '$1-$2');
  result = result.toLowerCase();
  result = result.replace(/^-/, '');
  result = result.replace(/-+$/, '');
  result = result.replace(/--+/g, '-');
  return result;
};

