function replaceAll(mainStr, searchStr, replaceStr) {
  let result = "";
  let lastIndex = 0;
  let searchLen = searchStr.length;

  if (searchLen === 0) {
    return mainStr;
  }

  while (true) {
    let index = mainStr.indexOf(searchStr, lastIndex);
    if (index === -1) {
      result += mainStr.substring(lastIndex);
      break;
    }
    result += mainStr.substring(lastIndex, index);
    result += replaceStr;
    lastIndex = index + searchLen;
  }
  return result;
}

