  if (!Array.isArray(words)) {
    return result;
  }

  for (let i = 0; i < words.length; i++) {
    const word = words[i];
    if (typeof word !== 'string' || word.length === 0) {
      continue;
    }
    const firstCharLower = word.charAt(0).toLowerCase();
    if (!result[firstCharLower]) {
      result[firstCharLower] = [];
    }
    result[firstCharLower].push(word);
  }

  return result;
};

