function getInitials(fullName) {
  let initials = '';
  if (fullName === null || fullName.trim() === '') {
    return initials;
  }
  const nameParts = fullName.split(' ');
  for (let i = 0; i < nameParts.length; i++) {
    const part = nameParts[i];
    if (part.length > 0) {
      initials += part[0].toUpperCase();
    }
  }
  return initials;
}

