const binToDec = (binaryString) => {
  let decimal = 0;
  const n = binaryString.length;
  for (let i = 0; i < n; i++) {
    const bit = parseInt(binaryString[i]);
    const power = n - 1 - i;
    decimal += bit * Math.pow(2, power);
  };
  return decimal;
};

