function getUniqueChars(str) {
  let seenChars = new Set();
  let result = "";

  for (let i = 0; i < str.length; i++) {
    let char = str[i];
    if (!seenChars.has(char)) {
      seenChars.add(char);
      result += char;
    }
  }
  return result;
}

