function countVowelsAndConsonants(str) {
    let vowels = 0;
    let consonants = 0;
    const vowelChars = new Set(['a', 'e', 'i', 'o', 'u']);

    for (let i = 0; i < str.length; i++) {
        const char = str[i].toLowerCase();

        if (char >= 'a' && char <= 'z') {
            if (vowelChars.has(char)) {
                vowels++;
            } else {
                consonants++;
            }
        }
    }

    return { vowels: vowels, consonants: consonants };
}

