const debounce = (func, delay) => {
  let timeoutId;

  return function(...args) {
    const context = this;

    clearTimeout(timeoutId);

    timeoutId = setTimeout(() => {
      func.apply(context, args);
    }, delay);
  };
};

const debouncedLog = debounce(() => console.log('Hello from debouncedLog'), 200);
debouncedLog();
debouncedLog();

const saveData = () => console.log('Data saved!');
const debouncedSave = debounce(saveData, 500);
debouncedSave();
setTimeout(() => debouncedSave(), 100);
setTimeout(() => debouncedSave(), 400);

