function generatePascalsRow(rowIndex) {
  if (rowIndex < 0) {
    throw new Error("Row index cannot be negative.");
  }

  if (rowIndex === 0) {
    return [1];
  }

  let currentRow = [1];
  let previousRow = [1];

  for (let i = 1; i <= rowIndex; i++) {
    currentRow = [1];
    for (let j = 1; j < i; j++) {
      currentRow.push(previousRow[j - 1] + previousRow[j]);
    }
    currentRow.push(1);
    previousRow = currentRow;
  }

  return currentRow;
}

