function clockAngle(hours, minutes) {
  let h = hours % 12;
  let m = minutes % 60;

  let hourAngle = (h * 30) + (m * 0.5);
  let minuteAngle = m * 6;

  let angleDifference = Math.abs(hourAngle - minuteAngle);

  let smallerAngle = Math.min(angleDifference, 360 - angleDifference);

  return smallerAngle;
}

