function convertBase10(num, base) {
  if (base < 2 || base > 36) {
    throw new Error("Base must be between 2 and 36 inclusive.");
  }
  if (num === 0) {
    return '0';
  }

  const digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  let result = "";
  let currentNum = Math.abs(num);

  while (currentNum > 0) {
    const remainder = currentNum % base;
    result = digits[remainder] + result;
    currentNum = Math.floor(currentNum / base);
  }

  if (num < 0) {
    result = '-' + result;
  }

  return result;
}

