function createEditor() {
  let states = [""];
  let currentIndex = 0;

  const typeText = (text) => {
    const newText = states[currentIndex] + text;
    states = states.slice(0, currentIndex + 1);
    states.push(newText);
    currentIndex++;
  };

  const undo = () => {
    if (currentIndex > 0) {
      currentIndex--;
    }
    return states[currentIndex];
  };

  const redo = () => {
    if (currentIndex < states.length - 1) {
      currentIndex++;
    }
    return states[currentIndex];
  };

  const getCurrentText = () => {
    return states[currentIndex];
  };

  return { typeText, undo, redo, getCurrentText };
}

