const trailingZerosInFactorial = (n) => {
  if (n < 0) {
    throw new Error("Input must be a non-negative integer.");
  }

  let count = 0;
  let powerOf5 = 5;

  while (n >= powerOf5) {
    count += Math.floor(n / powerOf5);
    powerOf5 *= 5;
  }

  return count;
};

