function closestPair1D(points) {
  if (points.length < 2) {
    return 0; // Or throw an error, depending on desired behavior for invalid input;
  }

  points.sort((a, b) => a - b); // Sort the array to easily find closest points;

  let minDistance = Infinity; // Initialize minDistance to a very large number;
  let i; // Declare loop variable outside;

  for (i = 0; i < points.length - 1; i++) {
    const currentDistance = points[i + 1] - points[i]; // Calculate distance between adjacent points;
    if (currentDistance < minDistance) {
      minDistance = currentDistance; // Update minDistance if a smaller one is found;
    }
  }
  return minDistance; // Return the smallest distance found;
}

