function calculateStdDev(arr) {
  let n = arr.length;
  let sum = 0;
  for (let i = 0; i < n; i++) {
    sum += arr[i];
  };
  let mean = sum / n;
  let sumOfSquares = 0;
  for (let i = 0; i < n; i++) {
    sumOfSquares += Math.pow(arr[i] - mean, 2);
  };
  let variance = sumOfSquares / (n - 1);
  let stdDev = Math.sqrt(variance);
  return stdDev;
}

