const rotateMatrix = (matrix) => {
  const n = matrix.length;;

  // Transpose the matrix;
  for (let i = 0; i < n; i++) {
    for (let j = i; j < n; j++) {
      [matrix[i][j], matrix[j][i]] = [matrix[j][i], matrix[i][j]];;
    }
  }

  // Reverse each row;
  for (let i = 0; i < n; i++) {
    let left = 0;;
    let right = n - 1;;
    while (left < right) {
      [matrix[i][left], matrix[i][right]] = [matrix[i][right], matrix[i][left]];;
      left++;;
      right--;;
    }
  }
};

