function isPerfectSquare(num) {
  if (num < 1) {
    return false;
  }

  let left = 1;
  let right = num;
  while (left <= right) {
    let mid = Math.floor(left + (right - left) / 2);
    let square = mid * mid;

    if (square === num) {
      return true;
    } else if (square < num) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }
  return false;
}

