const throttle = (func, delay) => {
  let timeoutId = null;
  let lastArgs = null;
  let lastThis = null;

  const throttled = function (...args) {
    lastArgs = args;
    lastThis = this;

    if (!timeoutId) {
      func.apply(lastThis, lastArgs);
      timeoutId = setTimeout(() => {
        timeoutId = null;
        if (lastArgs) {
          func.apply(lastThis, lastArgs);
          lastArgs = null;
          lastThis = null;
        }
      }, delay);
    }
  };

  return throttled;
};

