function convertBase(numStr, baseN, baseM) {
    if (baseN < 2 || baseN > 36 || baseM < 2 || baseM > 36) {
        throw new Error("Bases must be between 2 and 36.");
    }

    let decimalValue = parseInt(numStr, baseN);
    if (isNaN(decimalValue)) {
        throw new Error("Invalid number string for the given base.");
    }

    let result = decimalValue.toString(baseM);
    return result;
}

